// Home Health Aide Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: home-care judgment, disease-specific care and reporting.
import {q, mix} from './q.js';
const BAL='Balduzzi, Homemaker Home Health Aide', HART='Leahy, Fuzy & Grafe, Providing Home Care';
const RESP='Responsibilities and Legal/Ethical Issues', COMM='Effective Communication', INF='Infection Control and Safety', BODY='Body Systems and Common Disorders', SPEC='Caring for Special Populations', SKILL='Basic Healthcare Skills';

export default {
 id:'home-health-aide-1',
 event:'Home Health Aide',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Balduzzi’s Homemaker Home Health Aide and Hartman’s Providing Home Care',
 plan:[{area:RESP,weight:10},{area:COMM,weight:6},{area:INF,weight:10},{area:BODY,weight:40},{area:SPEC,weight:24},{area:SKILL,weight:10}],
 questions:mix([
  q(RESP,'Who develops the care plan that a home health aide follows?','The supervising nurse',['The home health aide','The client’s closest neighbor','The insurance company'],'C','The registered nurse or case manager assesses the client and writes the care plan. The aide follows it and reports changes or problems.',HART),
  q(RESP,'To receive Medicare home health benefits, a client must generally be:','Homebound and under a doctor’s care',['Over 85 years old','Living alone','Able to drive to appointments'],'A','Medicare covers home health care for clients who are homebound, under a physician’s plan of care and in need of skilled services such as nursing or therapy.',BAL),
  q(RESP,'A client who manages her own medications asks the aide to remind her to take them. What may the aide do?','Remind her and observe, but not give the medication',['Give her the correct pills from each bottle','Change the dose if she feels unwell','Refill her pill organizer from her prescriptions'],'B','Home health aides may remind clients to take self-administered medications and report what they observe, but they may not give, prepare or adjust medications.',HART),
  q(RESP,'An aide notices unexplained bruises on a client’s arms, and the client seems afraid of a family member. What should the aide do?','Report it to the supervisor right away',['Confront the family member','Ignore it unless the client complains','Post about it online to get advice'],'D','Possible abuse must be reported to the supervisor promptly. Aides are often mandated reporters; confronting suspected abusers can put the client at greater risk.',HART),
  q(RESP,'When should a home health aide document care?','Right after the care is given',['Before the care is given, to save time','At the end of the week','Only if something goes wrong'],'A','Documenting promptly after care keeps records accurate. Charting care before it is done is falsification of records.',HART),
  q(COMM,'Which approach is best when helping a client with dementia get dressed?','Give one simple instruction at a time',['Explain all the steps at once','Use long, detailed explanations','Ask open-ended questions about clothing choices'],'C','Short, simple, one-step directions and limited choices reduce confusion and frustration for people with dementia.',HART),
  q(COMM,'When caring for a client who is blind, what should the aide do on entering the room?','Identify yourself and your purpose',['Touch the client before speaking','Speak more loudly than usual','Rearrange furniture to make room'],'B','Announcing yourself prevents startling the client. Keep furniture and items in the same places, and describe locations using clock positions, such as “your cup is at 2 o’clock.”',HART),
  q(COMM,'A client says, “I don’t know if I can manage at home anymore.” Which response shows empathy?','“You sound worried about living on your own.”',['“Don’t worry, everything will be fine.”','“You should move to a nursing home.”','“Everyone feels that way sometimes.”'],'D','Reflecting the client’s feelings shows you are listening and invites them to say more. False reassurance and advice can shut down communication.',BAL),
  q(INF,'Which solution is commonly used in the home to disinfect surfaces contaminated with blood?','A 1:10 bleach solution',['Undiluted white vinegar','Soapy dishwater','Plain hot water'],'A','A freshly made 1:10 bleach solution disinfects surfaces after blood spills. Clean visible blood first while wearing gloves.',HART),
  q(INF,'How should a client’s used insulin needles be disposed of at home if no sharps container is available?','In a lidded heavy plastic bottle',['In a paper bag in the kitchen trash','In a plastic grocery bag','Flushed down the toilet with water'],'C','Used sharps go into a puncture-resistant container with a secure lid, labeled and disposed of according to local rules. Never recap needles or put them in thin bags.',HART),
  q(INF,'A client uses home oxygen. Which safety rule is most important?','No smoking or open flames near the oxygen',['Keep the tank lying on its side','Store the tank near the stove for warmth','Turn up the flow when the client is short of breath'],'B','Oxygen supports combustion, so fires burn hotter and faster. Post “No Smoking” signs, keep oxygen away from heat and flames, and never change the flow rate.',HART),
  q(INF,'To prevent scalds in the home, a water heater should be set no higher than about:','120 °F',['90 °F','140 °F','160 °F'],'D','Setting the water heater at or below 120 °F reduces burn risk, especially for older adults and children with thinner skin or slower reactions.',BAL),
  q(INF,'Which body mechanics practice helps protect the aide’s back when lifting?','Bend the knees and lift with the legs',['Bend at the waist with straight legs','Twist the body while lifting','Hold objects away from the body'],'A','Use a wide base of support, bend the knees, keep the back straight, hold objects close and pivot the feet instead of twisting.',HART),
  q(BODY,'A client with congestive heart failure is on a low-sodium diet. Why is sodium limited?','Sodium causes the body to retain fluid',['Sodium lowers blood pressure too much','Sodium damages the heart valves','Sodium blocks the heart medications'],'C','Sodium holds water in the body, adding to fluid overload, swelling and strain on a weak heart. Daily weights help detect fluid buildup.',HART),
  q(BODY,'A client with angina has chest pain that does not go away with rest and her prescribed nitroglycerin. What should the aide do?','Call 911 and notify the supervisor',['Have her lie down and wait an hour','Give her a second dose of someone else’s medicine','Tell her to walk to relieve the pain'],'B','Chest pain not relieved by rest or nitroglycerin may be a heart attack, which needs emergency care.',HART),
  q(BODY,'Which diet change is usually recommended for a client with high blood pressure?','Limiting salt',['Adding more salt','Eating mostly red meat','Increasing sugary drinks'],'D','Reducing sodium helps lower blood pressure. Other measures include weight control, exercise, limiting alcohol and taking medications as ordered.',BAL),
  q(BODY,'A client with COPD says he is short of breath and asks the aide to turn up his oxygen. What should the aide do?','Leave the flow as ordered and report it',['Turn the flow up to the highest setting','Turn the oxygen off for a while','Remove the nasal cannula'],'A','Aides never adjust oxygen. Some clients with COPD can be harmed by too much oxygen. Help the client sit upright, encourage pursed-lip breathing and report the change.',HART),
  q(BODY,'Which activity helps prevent pneumonia in a client recovering from illness at home?','Deep breathing and coughing',['Staying flat in bed all day','Limiting fluids','Keeping the room very cold'],'C','Deep breathing expands the lungs and coughing clears secretions, preventing pneumonia. Changing position and moving around also help.',BAL),
  q(BODY,'Why is daily foot care so important for clients with diabetes?','Nerve damage can hide injuries that get infected',['Diabetes makes the feet grow quickly in adults','Clients with diabetes cannot wear shoes','Foot care lowers blood sugar levels'],'B','Neuropathy can prevent a client from feeling a cut, and poor circulation slows healing. Inspect feet daily and report problems; aides do not cut a diabetic client’s toenails.',HART),
  q(BODY,'Which signs suggest high blood sugar in a client with diabetes?','Thirst, frequent urination, fruity breath',['Shakiness, sweating and hunger','Slow pulse and cold, clammy skin','Itching, hives and wheezing'],'D','Hyperglycemia develops more slowly and causes thirst, frequent urination, fatigue and sometimes fruity breath. Shakiness and sweating suggest low blood sugar.',HART),
  q(BODY,'An older client suddenly becomes confused, and her urine is cloudy and strong-smelling. What may this indicate?','A urinary infection',['Normal aging','A sprained ankle','Seasonal allergies'],'A','In older adults, new confusion may be the main sign of a UTI. Report the change, along with any fever or burning.',HART),
  q(BODY,'Which approach helps a client with urinary incontinence stay dry?','Offering the toilet on a regular schedule',['Limiting all fluids','Using adult briefs without changing them often','Scolding the client after accidents'],'C','Scheduled toileting (bladder training) helps the bladder empty regularly. Limiting fluids can cause dehydration and UTIs, and scolding harms dignity.',HART),
  q(BODY,'Which measures help prevent constipation?','Fluids, fiber and physical activity',['Bed rest and low-fiber foods','Avoiding water at meals','Holding back the urge to go'],'B','Adequate fluids, high-fiber foods, regular activity and responding promptly to the urge help keep bowel movements regular.',BAL),
  q(BODY,'A client with gastroesophageal reflux disease should be told to:','Avoid lying down soon after eating',['Eat one large meal at bedtime','Sleep completely flat','Drink coffee after each meal'],'D','Staying upright for a few hours after eating and raising the head of the bed help keep stomach acid out of the esophagus.',BAL),
  q(BODY,'Why is fall prevention especially important for a client with osteoporosis?','Weak bones break easily, even in minor falls',['Osteoporosis causes dizziness','Osteoporosis makes the skin fragile','Falls cause osteoporosis to spread'],'A','Osteoporosis reduces bone density, so a minor fall can fracture a hip, wrist or vertebra. Remove throw rugs, improve lighting and encourage safe footwear.',HART),
  q(BODY,'A client with arthritis has morning stiffness. What often helps before activity?','A warm bath or shower',['An ice bath','Complete bed rest for the day','Skipping all exercise'],'C','Warmth loosens stiff joints and eases pain. Gentle range-of-motion exercise as ordered helps keep joints flexible.',HART),
  q(BODY,'A client has a new arm cast. Which finding should be reported immediately?','Numbness and cool, pale fingers',['Mild itching under the cast','A dry cast surface','The client asking for a pillow'],'B','Numbness, tingling, coldness or color changes beyond a cast may mean the cast is too tight and blood flow or nerves are compromised.',HART),
  q(BODY,'After a stroke, a client cannot see the left half of her visual field. Where should the aide place food on the plate?','Where she can see it',['Only on the left side of the plate','Under a cover so it stays warm','On a tray behind her'],'D','With hemianopia, the client may eat only the food she can see. Place items in her field of vision, turn the plate and remind her to scan.',HART),
  q(BODY,'A client with multiple sclerosis tires easily. How can the aide help?','Plan rest periods between activities',['Schedule all activities back to back','Keep the home very warm','Discourage any exercise'],'A','Fatigue is common in MS, and heat can worsen symptoms. Pacing activities with rest helps the client stay independent longer.',BAL),
  q(BODY,'A client begins having a seizure. What should the aide do?','Protect the head and time the seizure',['Hold the client down','Put a spoon in the client’s mouth','Give the client water'],'C','Move objects away, cushion the head and never restrain or put anything in the mouth. Time the seizure and call 911 if it lasts more than 5 minutes.',HART),
  q(BODY,'Which symptom is typical of a cataract?','Cloudy, blurred vision with glare',['Sudden loss of all vision in one eye','Eye pain with a red, swollen eyelid','Seeing perfectly in dim light'],'B','A cataract is clouding of the lens that causes blurred vision, glare and trouble seeing at night. It is often treated with lens replacement surgery.',BAL),
  q(BODY,'Which areas are most at risk for pressure injuries in a client who lies on her back?','The sacrum and heels',['The palms and fingers','The abdomen and chest','The knees and shins'],'D','Pressure injuries form over bony prominences. Lying on the back puts pressure on the back of the head, shoulder blades, elbows, sacrum and heels.',HART),
  q(BODY,'A client receiving chemotherapy has a very low white blood cell count. What should the aide do?','Use careful hand hygiene and keep sick visitors away',['Encourage the client to visit crowded places','Serve raw sushi to boost protein','Skip hand hygiene to save time'],'A','Low white blood cell counts (neutropenia) greatly increase infection risk. Good hand hygiene, food safety and avoiding sick contacts protect the client.',BAL),
  q(SPEC,'A client with Alzheimer’s disease wanders and has left the house at night. Which safety measure helps?','Door alarms or chimes',['Locking the client in a room','Giving extra sleeping pills','Removing all lights at night'],'C','Door alarms alert caregivers without restricting the client. Locking a client in a room is a restraint, and aides never give extra medication.',HART),
  q(SPEC,'A client with dementia becomes suddenly upset and starts crying and shouting during a noisy family visit. What should the aide do?','Calmly move to a quieter place',['Raise your voice to be heard','Argue to calm the client down','Leave the client alone'],'B','This is a catastrophic reaction to overstimulation. Lowering noise and activity, speaking softly and redirecting help the client calm down.',HART),
  q(SPEC,'Why should caregivers keep talking gently to a dying client who no longer responds?','Hearing may be the last sense to be lost',['It speeds the dying process','It keeps the client from feeling pain','It is required for documentation'],'D','Hearing is believed to remain until very late, so speaking softly and explaining care can comfort the client.',HART),
  q(SPEC,'A new mother at home is soaking a large pad every hour and passing large clots. What should the aide do?','Report it immediately',['Tell her this is normal lochia','Have her drink coffee','Wait until the next visit to report it'],'A','Heavy bleeding with large clots may signal postpartum hemorrhage, an emergency. Normal lochia decreases over days and does not soak a pad hourly.',BAL),
  q(SPEC,'How should a newborn’s umbilical cord stump be cared for at home?','Keep it clean and dry',['Cover it tightly with plastic','Soak it in the bath daily','Pull it off after a few days'],'C','The stump usually falls off in 1–3 weeks. Keep the diaper folded below it, and report redness, swelling, foul odor or bleeding.',BAL),
  q(SPEC,'In which position should a healthy infant be placed to sleep?','On the back',['On the stomach','On the side, propped with pillows','Sitting in a car seat'],'B','Back sleeping on a firm surface without pillows, blankets or toys lowers the risk of sudden infant death syndrome.',BAL),
  q(SPEC,'An aide is helping a 6-year-old with a chronic illness. How should procedures be explained?','In simple words suited to the child’s age',['With detailed medical terms','Only to the parents, never to the child','Not at all, to avoid fear'],'D','Using age-appropriate language and honest, simple explanations reduces fear and helps children cooperate.',BAL),
  q(SPEC,'A client with depression tells the aide, “Everyone would be better off without me.” What should the aide do?','Report it immediately',['Change the subject gently','Promise to keep it secret','Tell the client to cheer up'],'A','Statements about death or being a burden can signal suicide risk and must be reported right away. Do not leave a client alone if they are in immediate danger.',HART),
  q(SPEC,'How should an aide support a client with an intellectual disability?','Encourage the client to do as much as possible independently',['Do every task for the client to save time','Speak to the client as if they were a small child','Make all of the client’s choices for them'],'C','Promoting independence and offering choices builds skills and dignity. Break tasks into small steps and give praise for effort.',HART),
  q(SPEC,'Which precautions does an aide use when caring for a client with HIV?','Standard precautions',['Airborne precautions','Droplet precautions','No precautions, because HIV is not spread by contact'],'B','HIV spreads through blood and certain body fluids, not casual contact. Standard precautions, used with every client, protect against bloodborne pathogens.',HART),
  q(SPEC,'A client receiving hospice care has a very dry mouth. What should the aide do?','Give frequent mouth care',['Stop all mouth care for comfort','Force large amounts of fluid','Leave the mouth open to air-dry'],'D','Comfort is the goal in hospice. Frequent mouth care, small sips if the client can swallow and lip balm ease dryness.',HART),
  q(SPEC,'A daughter caring for her father full-time seems exhausted and irritable. Which service could help?','Respite care',['Acute hospital care','Rehabilitation therapy','Emergency surgery'],'A','Respite care gives family caregivers a temporary break by having someone else care for the client, helping prevent caregiver burnout.',BAL),
  q(SKILL,'Where is the stethoscope placed to count an apical pulse?','Over the apex of the heart',['On the thumb side of the inner wrist','On the side of the neck','On the inside of the elbow'],'C','The apical pulse is heard over the apex of the heart, about the left midclavicular line at the fifth intercostal space, and is counted for a full minute.',HART),
  q(SKILL,'When making an occupied bed, how is the client kept safe and covered?','Keep the client covered and the far rail up',['Remove all linens while the client lies uncovered','Leave both side rails down at all times','Have the client stand during the bed change'],'A','The client stays covered for warmth and privacy, and the far side rail is raised (if used) so the client cannot roll out of bed while turned.',HART),
  q(SKILL,'A client on a tight budget needs inexpensive protein foods. Which choice is best?','Dried beans and eggs',['Steak and shrimp','Protein bars','Deli meats only'],'B','Dried beans, lentils, eggs and peanut butter are low-cost, nutritious protein sources.',BAL),
  q(SKILL,'What is the safest way to thaw frozen meat in a client’s home?','In the refrigerator',['On the kitchen counter','In a sink of hot water','Outside in the sun'],'D','Thawing in the refrigerator keeps meat out of the temperature danger zone (40–140 °F) where bacteria multiply quickly.',HART),
  q(SKILL,'A client with weakness on the right side uses a cane. On which side should the cane be held?','The left (strong) side',['The right (weak) side','Either side','Both hands together'],'C','The cane is held on the strong side and moves forward with the weak leg, providing support where it is needed.',HART)
 ],61)
};
